def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    DIV0 = "#DIV/0!"
    CYCLE = "#CYCLE!"
    tokens_re = re.compile(
        r"\s*(?:(\d+)|([A-Z](?:[1-9]\d?))|(<=|>=|<>|[()+\-*/,:=<>])|([A-Z]+))"
    )

    class Parser:
        def __init__(self, text):
            self.tokens = []
            pos = 0
            while pos < len(text):
                match = tokens_re.match(text, pos)
                if not match:
                    raise ValueError("Invalid formula")
                number, cell, op, word = match.groups()
                self.tokens.append(
                    number if number is not None else
                    cell if cell is not None else
                    op if op is not None else word
                )
                pos = match.end()
            self.i = 0

        def peek(self):
            return self.tokens[self.i] if self.i < len(self.tokens) else None

        def take(self, expected=None):
            token = self.peek()
            if token is None or (expected is not None and token != expected):
                raise ValueError("Invalid formula")
            self.i += 1
            return token

        def formula(self):
            return self.additive()

        def additive(self):
            node = self.multiplicative()
            while self.peek() in ("+", "-"):
                op = self.take()
                node = ("bin", op, node, self.multiplicative())
            return node

        def multiplicative(self):
            node = self.unary()
            while self.peek() in ("*", "/"):
                op = self.take()
                node = ("bin", op, node, self.unary())
            return node

        def unary(self):
            if self.peek() == "-":
                self.take()
                return ("neg", self.unary())
            return self.atom()

        def atom(self):
            token = self.peek()
            if token == "(":
                self.take("(")
                node = self.formula()
                self.take(")")
                return node
            if token is None:
                raise ValueError("Invalid formula")
            if token.isdigit():
                self.take()
                return ("num", int(token))
            if len(token) >= 2 and token[0].isalpha() and token[0].isupper() and token[1:].isdigit():
                self.take()
                return ("ref", token)
            if token in ("SUM", "MIN", "MAX", "IF"):
                name = self.take()
                self.take("(")
                if name == "IF":
                    left = self.formula()
                    op = self.take()
                    if op not in ("=", "<>", "<", "<=", ">", ">="):
                        raise ValueError("Invalid formula")
                    right = self.formula()
                    self.take(",")
                    then = self.formula()
                    self.take(",")
                    otherwise = self.formula()
                    self.take(")")
                    return ("if", op, left, right, then, otherwise)

                args = [self.function_arg()]
                while self.peek() == ",":
                    self.take(",")
                    args.append(self.function_arg())
                self.take(")")
                return ("func", name, args)
            raise ValueError("Invalid formula")

        def function_arg(self):
            if self.i + 1 < len(self.tokens) and self.tokens[self.i + 1] == ":":
                first = self.take()
                self.take(":")
                second = self.take()
                return ("range", first, second)
            return ("expr", self.formula())

    parsed = {}
    for name, content in cells.items():
        if content.startswith("="):
            parser = Parser(content[1:])
            parsed[name] = parser.formula()
        else:
            parsed[name] = int(content)

    state = {}
    values = {}

    def coord(name):
        return ord(name[0]) - ord("A"), int(name[1:]) - 1

    def cell_value(name):
        if name not in cells:
            return 0
        if state.get(name) == 1:
            return CYCLE
        if state.get(name) == 2:
            return values[name]

        state[name] = 1
        value = parsed[name] if isinstance(parsed[name], int) else eval_node(parsed[name])
        values[name] = value
        state[name] = 2
        return value

    def eval_node(node):
        kind = node[0]
        if kind == "num":
            return node[1]
        if kind == "ref":
            return cell_value(node[1])
        if kind == "neg":
            value = eval_node(node[1])
            return value if isinstance(value, str) else -value
        if kind == "bin":
            _, op, left_node, right_node = node
            left = eval_node(left_node)
            if isinstance(left, str):
                return left
            right = eval_node(right_node)
            if isinstance(right, str):
                return right
            if op == "+":
                return left + right
            if op == "-":
                return left - right
            if op == "*":
                return left * right
            if right == 0:
                return DIV0
            quotient = abs(left) // abs(right)
            return -quotient if (left < 0) != (right < 0) else quotient
        if kind == "if":
            _, op, left_node, right_node, then_node, else_node = node
            left = eval_node(left_node)
            if isinstance(left, str):
                return left
            right = eval_node(right_node)
            if isinstance(right, str):
                return right
            condition = {
                "=": left == right,
                "<>": left != right,
                "<": left < right,
                "<=": left <= right,
                ">": left > right,
                ">=": left >= right,
            }[op]
            return eval_node(then_node if condition else else_node)

        _, name, args = node
        items = []
        for arg in args:
            if arg[0] == "expr":
                value = eval_node(arg[1])
                if isinstance(value, str):
                    return value
                items.append(value)
            else:
                _, first, second = arg
                col1, row1 = coord(first)
                col2, row2 = coord(second)
                for row in range(min(row1, row2), max(row1, row2) + 1):
                    for col in range(min(col1, col2), max(col1, col2) + 1):
                        cell = chr(ord("A") + col) + str(row + 1)
                        if cell in cells:
                            value = cell_value(cell)
                            if isinstance(value, str):
                                return value
                            items.append(value)
        if name == "SUM":
            return sum(items)
        if name == "MIN":
            return min(items) if items else 0
        return max(items) if items else 0

    return {name: cell_value(name) for name in cells}
